INSERT INTO subjects (name, description) VALUES ('DSA', 'Data structures and algorithms: arrays, trees, graphs and complexity analysis.');
INSERT INTO subjects (name, description) VALUES ('DBMS', 'Database management systems: relational design, normalization and transactions.');
INSERT INTO subjects (name, description) VALUES ('SQL', 'Structured Query Language: querying, joins, indexing and optimization.');
INSERT INTO subjects (name, description) VALUES ('Computer Networks', 'Networking fundamentals: layered models, transport and application protocols.');
INSERT INTO subjects (name, description) VALUES ('Operating Systems', 'Operating system concepts: processes, scheduling and memory management.');
INSERT INTO subjects (name, description) VALUES ('Aptitude', 'Quantitative and logical reasoning for placement tests.');
INSERT INTO subjects (name, description) VALUES ('Full Stack Development', 'Building complete web applications with a frontend, a backend and a database.');
INSERT INTO subjects (name, description) VALUES ('Projects', 'Planning, building and presenting portfolio projects.');
